return {
    property: "DisplayName", // Default column to search
    operation: "contains", // Default operator
    label: "Name" // Human readable label for the placeholder
}

const displayColumnNames = [
    "Name",          // Mapped from DisplayName
    "StartDate",
    "EndDate",
    "PayDate",
    "WorkDays",
    "Status",
    "OffCycle"
];

const displayColumnOptions = {
    valueKey: {
        "Name": "DisplayName",
    },
    type: {
        "StartDate": "date",
        "EndDate": "date",
        "PayDate": "date",
        "SubmitDate": "date",
        "OffCycle": "boolean",
        // "FinalPayEligibleWorker": "boolean"
    },
    // config: {
    //     "WorkDays": { align: "right", width: "100px" },
    //     "Status": { width: "120px" }
    // }
};

return {
    columnKeys: displayColumnNames,
    options: displayColumnOptions
};

return [
